<script>
document.addEventListener('DOMContentLoaded',()=>{
 document.querySelectorAll('.employee-reference').forEach(select=>select.dataset.search='off');
 const fallbackModalElement=document.getElementById('stage-builder-modal');
 if(!window.bootstrap){window.bootstrap={Modal:class{constructor(element){this.element=element}show(){this.element.style.display='block';this.element.style.background='rgba(2,6,23,.76)';this.element.classList.add('show');this.element.setAttribute('aria-hidden','false');document.body.classList.add('modal-open')}hide(){this.element.style.display='none';this.element.style.background='';this.element.classList.remove('show');this.element.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}}};document.querySelectorAll('[data-bs-dismiss="modal"]').forEach(button=>button.addEventListener('click',()=>fallbackModalElement?new window.bootstrap.Modal(fallbackModalElement).hide():null));fallbackModalElement?.addEventListener('click',event=>{if(event.target===fallbackModalElement)new window.bootstrap.Modal(fallbackModalElement).hide()})}
 const typeMeta=@json($stepTypes),csrf=document.querySelector('meta[name="csrf-token"]')?.getAttribute('content'),list=document.getElementById('workflow-list'),canvas=document.getElementById('workflow-canvas'),inspector=document.getElementById('node-inspector'),inspectorEmpty=document.getElementById('inspector-empty'),builder=document.getElementById('stage-builder-form'),modalElement=document.getElementById('stage-builder-modal'),modal=window.bootstrap&&modalElement?new bootstrap.Modal(modalElement):null,employeeReferenceTypes=['employee','department_manager','asset_manager','warehouse_manager'];
 const autoCode=type=>`${(type||'STEP').toUpperCase()}-${Date.now().toString().slice(-8)}`;
 function filterEmployees(input){const select=input.closest('.approver-reference-wrap')?.querySelector('.employee-reference');if(!select)return;const needle=input.value.trim().toLocaleLowerCase('fa-IR');Array.from(select.options).forEach((option,index)=>option.hidden=index>0&&!option.textContent.toLocaleLowerCase('fa-IR').includes(needle))}
 function configureApprover(scope,value=undefined,reference=''){if(!scope)return;const type=scope.querySelector('.approver-type'),wrapper=scope.querySelector('.approver-reference-wrap'),employee=scope.querySelector('.employee-reference'),role=scope.querySelector('.role-reference'),hidden=scope.querySelector('.approver-reference-id'),label=scope.querySelector('.reference-label'),hint=scope.querySelector('#builder-approver-hint');if(!type||!hidden)return;if(value!==undefined)type.value=value||'';const current=type.value;wrapper?.classList.add('d-none');employee?.classList.add('d-none');role?.classList.add('d-none');hidden.value='';if(employeeReferenceTypes.includes(current)){wrapper?.classList.remove('d-none');employee?.classList.remove('d-none');if(employee)employee.value=reference||'';hidden.value=reference||'';if(label)label.textContent='پرسنل مسئول مرحله'}if(current==='role'){wrapper?.classList.remove('d-none');role?.classList.remove('d-none');if(role)role.value=reference||'';hidden.value=reference||'';if(label)label.textContent='نقش مسئول مرحله'}if(hint)hint.textContent=current?'مسئول مرحله را می‌توانید بعداً هم تغییر دهید.':'برای مرحلهٔ تأیید، مسئول را مشخص کنید.'}
 function selectStep(card){if(!card||!inspector)return;const id=card.dataset.stepId;document.querySelectorAll('.workflow-step-card.selected').forEach(item=>item.classList.remove('selected'));document.querySelectorAll(`.workflow-step-card[data-step-id="${id}"]`).forEach(item=>item.classList.add('selected'));inspector.classList.remove('d-none');inspectorEmpty?.classList.add('d-none');inspector.action=`${inspector.dataset.updateBase}/${id}`;document.getElementById('inspector-heading').textContent=card.dataset.name;document.getElementById('inspector-name').value=card.dataset.name||'';document.getElementById('inspector-code').value=card.dataset.code||'';document.getElementById('inspector-type').value=card.dataset.type||'approval';document.getElementById('inspector-due').value=card.dataset.dueHours||'';document.getElementById('inspector-rejection').value=card.dataset.rejection||'terminate';document.getElementById('inspector-description').value=card.dataset.description||'';document.getElementById('inspector-required').checked=card.dataset.required==='1';document.getElementById('inspector-active').checked=card.dataset.active==='1';const meta=typeMeta[card.dataset.type]||typeMeta.condition,icon=document.getElementById('inspector-icon');icon.className=`stage-type ${meta.class}`;icon.textContent=meta.icon;configureApprover(inspector,card.dataset.approverType,card.dataset.approverReference)}
 function openBuilder(preset={}){if(!builder)return;builder.reset();const type=preset.type||'approval';document.getElementById('builder-name').value=preset.name||'';document.getElementById('builder-type').value=type;document.getElementById('builder-code').value=preset.code||autoCode(type);document.getElementById('builder-code').dataset.auto=preset.code?'false':'true';document.getElementById('builder-due').value=preset.dueHours||'';document.getElementById('builder-rejection').value=preset.rejection||'terminate';document.getElementById('builder-description').value=preset.description||'';configureApprover(builder,preset.approver||(type==='approval'?'direct_manager':'system'),preset.reference||'');modal?.show();setTimeout(()=>document.getElementById('builder-name')?.focus(),180)}
 async function saveOrder(){if(!list?.dataset.reorderUrl)return;const ids=Array.from(list.querySelectorAll('.workflow-step-card')).map(card=>Number(card.dataset.stepId));if(!ids.length)return;const response=await fetch(list.dataset.reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({step_ids:ids})});if(!response.ok)throw new Error('reorder failed');window.location.reload()}
 document.querySelectorAll('.workflow-step-select,.flow-node').forEach(element=>element.addEventListener('click',event=>selectStep(event.currentTarget.closest('.workflow-step-card'))));document.getElementById('new-stage-button')?.addEventListener('click',()=>openBuilder());document.querySelectorAll('.quick-suggestion').forEach(button=>button.addEventListener('click',()=>openBuilder({type:button.dataset.type,approver:button.dataset.approver,name:button.dataset.name})));document.querySelectorAll('.approver-type').forEach(select=>select.addEventListener('change',()=>configureApprover(select.closest('form'))));document.querySelectorAll('.employee-reference,.role-reference').forEach(select=>select.addEventListener('change',()=>{if(!select.classList.contains('d-none'))select.closest('form').querySelector('.approver-reference-id').value=select.value}));document.querySelectorAll('.employee-search').forEach(input=>input.addEventListener('input',()=>filterEmployees(input)));document.getElementById('builder-type')?.addEventListener('change',event=>{const code=document.getElementById('builder-code');if(code&&(!code.value||code.dataset.auto==='true')){code.value=autoCode(event.target.value);code.dataset.auto='true'}});document.getElementById('builder-code')?.addEventListener('input',event=>event.target.dataset.auto='false');
 document.querySelectorAll('.view-switch').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.view-switch').forEach(item=>item.classList.toggle('active',item===button));document.querySelectorAll('.view-panel').forEach(panel=>panel.classList.toggle('active',panel.id===`view-${button.dataset.view}`))}));document.querySelectorAll('.move-step').forEach(button=>button.addEventListener('click',async event=>{const row=event.currentTarget.closest('.workflow-step-card'),sibling=event.currentTarget.dataset.direction==='up'?row.previousElementSibling:row.nextElementSibling;if(!sibling?.matches('.workflow-step-card'))return;event.currentTarget.disabled=true;if(event.currentTarget.dataset.direction==='up')sibling.before(row);else sibling.after(row);try{await saveOrder()}catch{alert('ترتیب مرحله ذخیره نشد. لطفاً دوباره تلاش کنید.');event.currentTarget.disabled=false}}));document.querySelectorAll('.duplicate-step').forEach(button=>button.addEventListener('click',event=>{const card=event.currentTarget.closest('.workflow-step-card');openBuilder({name:`${card.dataset.name} (کپی)`,type:card.dataset.type,approver:card.dataset.approverType,reference:card.dataset.approverReference,dueHours:card.dataset.dueHours,rejection:card.dataset.rejection,description:card.dataset.description})}));document.querySelectorAll('.delete-step').forEach(button=>button.addEventListener('click',event=>{const card=event.currentTarget.closest('.workflow-step-card');if(!window.confirm(`مرحله «${card.dataset.name}» حذف شود؟`))return;const form=document.getElementById('delete-stage-form');form.action=`${inspector.dataset.updateBase}/${card.dataset.stepId}`;form.submit()}));
 let dragging=null;canvas?.querySelectorAll('.flow-node[data-step-id]').forEach(node=>{node.addEventListener('dragstart',()=>{dragging=node;node.classList.add('dragging')});node.addEventListener('dragend',()=>{node.classList.remove('dragging');dragging=null});node.addEventListener('dragover',event=>{event.preventDefault();if(!dragging||dragging===node)return;const rect=node.getBoundingClientRect(),connector=node.nextElementSibling;if(event.clientX<rect.left+rect.width/2)node.before(dragging,dragging.nextElementSibling);else connector.after(dragging,dragging.nextElementSibling)})});canvas?.addEventListener('drop',async event=>{event.preventDefault();const ids=Array.from(canvas.querySelectorAll('.flow-node[data-step-id]')).map(node=>Number(node.dataset.stepId));if(!ids.length)return;try{const response=await fetch(canvas.dataset.reorderUrl,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrf},body:JSON.stringify({step_ids:ids})});if(!response.ok)throw new Error();window.location.reload()}catch{alert('ترتیب جدید ذخیره نشد. لطفاً دوباره تلاش کنید.')}});const first=document.querySelector('.workflow-step-card[data-step-id]');if(first)selectStep(first);
});
